MONTHS = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
WEEKDAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]

DEFECT_NOUL_THRESHOLD = 0.5
DATE_REVIEW_CONFIDENCE_FLOOR = 0.60


def _split_sentences(text: str) -> list[str]:
    parts = re.split(r"(?<=[.!?])\s+", text.strip())
    return [p.strip() for p in parts if p.strip()]


def _defect_questions(already_reported: list[str]) -> dict[str, Noul]:
    return {
        "is_defective": Noul(
            instructions=(
                "Does `sentence` claim that a specific product is defective, broken, "
                "damaged, or not working?"
            ),
            criteria=NoulCriteria(
                true="Names or clearly identifies a specific product and says it is defective/broken/not working.",
                false="No specific defective product is named here.",
            ),
        ),
        "is_new_product": Noul(
            instructions=(
                "If `sentence` claims a product is defective, is that product different from "
                "every product already listed in `already_reported`? Answer yes if "
                "`already_reported` is empty."
            ),
            criteria=NoulCriteria(
                true="The product in `sentence` is not any of the products in `already_reported`.",
                false="The product in `sentence` is the same product as one already in `already_reported`.",
            ),
        ),
    }


def _count_distinct_defective_products(client: TypeSafeClient, email_text: str) -> int:
    confirmed: list[str] = []
    for sentence in _split_sentences(email_text):
        r = client.system_one(
            state={"sentence": sentence, "already_reported": confirmed},
            questions=_defect_questions(confirmed),
            model=MODEL,
        )
        is_defective = r.nouls["is_defective"].noul
        is_new_product = r.nouls["is_new_product"].noul
        if is_defective > DEFECT_NOUL_THRESHOLD and is_new_product > DEFECT_NOUL_THRESHOLD:
            confirmed.append(sentence)
    return len(confirmed)


def _date_questions() -> dict[str, Choice]:
    year_criteria = {str(y): None for y in range(1900, 2051)}
    year_criteria["out_of_range"] = "The year is stated but outside 1900-2050."
    year_criteria["none"] = "No year is stated, or the date is not absolute."

    return {
        "mode": Choice(
            instructions=(
                "Does `email_text` promise a delivery date, and is it given as an absolute "
                "calendar date, a relative description (e.g. 'tomorrow', 'next Monday'), or "
                "is no delivery date promised at all?"
            ),
            criteria={"absolute": None, "relative": None, "none": "No delivery date is promised in `email_text`."},
        ),
        "month": Choice(
            instructions="If `email_text` states an absolute promised delivery date, which month is it?",
            criteria={m: None for m in MONTHS} | {"none": "No month is stated, or the date is not absolute."},
        ),
        "day": Choice(
            instructions="If `email_text` states an absolute promised delivery date, which day of the month is it?",
            criteria={str(d): None for d in range(1, 32)} | {"none": "No day of month is stated, or the date is not absolute."},
        ),
        "year": Choice(
            instructions=(
                "If `email_text` states an absolute promised delivery date with an explicit "
                "year, which year is it?"
            ),
            criteria=year_criteria,
        ),
        "day_anchor": Choice(
            instructions=(
                "If `email_text` states a relative promised delivery date, is it today, "
                "tomorrow, the day after tomorrow, or tied to a named weekday?"
            ),
            criteria={
                "today": None, "tomorrow": None, "day_after": None, "weekday": None,
                "none": "The date is not relative, or none is stated.",
            },
        ),
        "weekday": Choice(
            instructions=(
                "If the promised delivery date is relative and anchored to a named weekday, "
                "which day of the week is it?"
            ),
            criteria={w: None for w in WEEKDAYS} | {"none": "No weekday is stated, or the date is not anchored to one."},
        ),
        "week_offset": Choice(
            instructions=(
                "If the promised delivery date is anchored to a named weekday, is it the "
                "current week or next week?"
            ),
            criteria={"current": None, "next": None, "none": "The date is not anchored to a weekday."},
        ),
    }


def _resolve_weekday(today: datetime.date, weekday_name: str, week_offset: str) -> datetime.date | None:
    if weekday_name == "none":
        return None
    target = WEEKDAYS.index(weekday_name)
    days_ahead = (target - today.weekday()) % 7
    if week_offset == "next":
        days_ahead += 7
    return today + datetime.timedelta(days=days_ahead)


def _assemble_date(
    today: datetime.date,
    mode: str,
    month: str,
    day: str,
    year: str,
    day_anchor: str,
    weekday: str,
    week_offset: str,
) -> datetime.date | None:
    if mode == "absolute":
        if month == "none" or day == "none":
            return None
        month_num = MONTHS.index(month) + 1
        day_num = int(day)
        year_num = int(year) if year not in ("none", "out_of_range") else today.year
        try:
            candidate = datetime.date(year_num, month_num, day_num)
        except ValueError:
            return None
        if year in ("none", "out_of_range") and (candidate - today).days < -31:
            candidate = datetime.date(year_num + 1, month_num, day_num)
        return candidate
    if mode == "relative":
        if day_anchor == "today":
            return today
        if day_anchor == "tomorrow":
            return today + datetime.timedelta(days=1)
        if day_anchor == "day_after":
            return today + datetime.timedelta(days=2)
        if day_anchor == "weekday":
            return _resolve_weekday(today, weekday, week_offset)
        return None
    return None


def check_email(email_text: str, today: datetime.date) -> dict:
    """Read a customer email with Jev and report the distinct defective-product
    count and whether the promised delivery date has already passed."""
    with TypeSafeClient() as client:
        defective_product_count = _count_distinct_defective_products(client, email_text)

        date_r = client.system_one(
            state={"email_text": email_text},
            questions=_date_questions(),
            model=MODEL,
        )
        mode = date_r.choices["mode"].choice
        month = date_r.choices["month"].choice
        day = date_r.choices["day"].choice
        year = date_r.choices["year"].choice
        day_anchor = date_r.choices["day_anchor"].choice
        weekday = date_r.choices["weekday"].choice
        week_offset = date_r.choices["week_offset"].choice

        promised_date = _assemble_date(today, mode, month, day, year, day_anchor, weekday, week_offset)

        if mode == "absolute":
            used_parts = ("mode", "month", "day", "year")
        elif mode == "relative":
            used_parts = ("mode", "day_anchor", "weekday", "week_offset")
        else:
            used_parts = ("mode",)
        date_confidence = min(date_r.choices[part].confidence for part in used_parts)

        needs_review = date_confidence < DATE_REVIEW_CONFIDENCE_FLOOR or (mode != "none" and promised_date is None)

    return {
        "defective_product_count": defective_product_count,
        "delivery_date_passed": promised_date is not None and promised_date < today,
        "promised_delivery_date": promised_date.isoformat() if promised_date else None,
        "needs_review": needs_review,
    }

#!/usr/bin/env python3
"""Flag log lines that need an on-call engineer, using typesafe.ai's Jev model."""

import argparse
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed

from typesafe_sdk import Noul, TypeSafeClient, TypeSafeError

BATCH_SIZE = 20            # lines per Jev request; keeps state well under the 64k-token cap
MAX_WORKERS = 8            # shared-key rate limit ceiling (typesafe.ai rate-limits above ~8 workers)
ON_CALL_THRESHOLD = 0.70   # Noul band: >0.70 = yes (patterns.md); re-tune once you have labeled data

ON_CALL_INSTRUCTIONS = (
    "Does `lines[{i}]` describe something that needs an on-call engineer to "
    "respond right now -- e.g. a service outage, crash, unhandled exception, "
    "failed health check, data loss, security incident, or an SLA/error-budget "
    "breach? Answer no for routine INFO/DEBUG output, expected warnings, or "
    "errors that are already marked resolved/retried successfully."
)


def make_questions(batch_len: int) -> dict:
    return {
        f"l{i}": Noul(instructions=ON_CALL_INSTRUCTIONS.format(i=i))
        for i in range(batch_len)
    }


def label_batch(client: TypeSafeClient, batch: list[str]):
    """Returns (list[bool] flagged-per-line, model_id_or_None)."""
    if not batch:
        return [], None
    try:
        r = client.system_one(state={"lines": batch}, questions=make_questions(len(batch)))
        flags = [r.nouls[f"l{i}"].noul > ON_CALL_THRESHOLD for i in range(len(batch))]
        return flags, r.model
    except TypeSafeError as e:
        print(f"warning: batch of {len(batch)} lines failed ({e}); flagging for manual review",
              file=sys.stderr)
        return [True] * len(batch), None


def chunked(seq: list, size: int):
    for i in range(0, len(seq), size):
        yield seq[i:i + size]


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("logfile")
    parser.add_argument("-o", "--output", default="flagged.txt")
    parser.add_argument("--batch-size", type=int, default=BATCH_SIZE)
    parser.add_argument("--workers", type=int, default=MAX_WORKERS)
    args = parser.parse_args()

    with open(args.logfile, encoding="utf-8", errors="replace") as f:
        lines = [line.rstrip("\n") for line in f]

    non_empty_idx = [i for i, line in enumerate(lines) if line.strip()]
    idx_batches = list(chunked(non_empty_idx, args.batch_size))

    flagged = [False] * len(lines)
    models_seen: set[str] = set()

    with TypeSafeClient() as client, ThreadPoolExecutor(max_workers=args.workers) as pool:
        futures = {
            pool.submit(label_batch, client, [lines[i] for i in idx_batch]): idx_batch
            for idx_batch in idx_batches
        }
        for future in as_completed(futures):
            idx_batch = futures[future]
            results, model = future.result()
            if model:
                models_seen.add(model)
            for i, is_flagged in zip(idx_batch, results):
                flagged[i] = is_flagged

    with open(args.output, "w", encoding="utf-8") as out:
        for line, is_flagged in zip(lines, flagged):
            if is_flagged:
                out.write(line + "\n")

    print(f"{sum(flagged)} of {len(lines)} lines flagged -> {args.output}")
    if models_seen:
        print(f"answered by: {', '.join(sorted(models_seen))}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Flag application log lines that need an on-call engineer, using typesafe.ai's Jev model."""

import argparse
import re
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed

from typesafe_sdk import Noul, TypeSafeClient, TypeSafeError

# --- tunables -------------------------------------------------------------

MODEL = "jev-1.13.0"          # pin the version thresholds below were chosen for
BATCH_SIZE = 50               # log lines judged per request (state dominates tokens, not question count)
MAX_WORKERS = 8               # shared-key rate limit starts biting above ~8 concurrent workers
NOUL_THRESHOLD = 0.8          # P(needs on-call) above which a line is flagged

# Broad recall net: only lines that look even remotely like trouble are sent
# to Jev. On a typical app log this cuts the model-call volume by 90%+ before
# any judgment call is made, which is where the real time/cost goes on 50k lines.
CANDIDATE_PATTERN = re.compile(
    r"error|warn|exception|fail|panic|fatal|critical|timeout"
    r"|denied|refused|unreachable|crash|traceback|deadlock|oom"
    r"|\b5\d\d\b",
    re.IGNORECASE,
)


def question_text(index: int) -> str:
    return (
        f"Does `lines.{index}` describe a problem serious enough to page an "
        "on-call engineer right now (an outage, crash, data loss, security "
        "incident, or an unrecoverable/production-impacting error), as opposed "
        "to routine, informational, retried-and-recovered, or already-handled "
        "output?"
    )


def read_candidates(path):
    """Yield (line_number, text) for lines worth sending to Jev."""
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for lineno, line in enumerate(f):
            text = line.rstrip("\n")
            if text and CANDIDATE_PATTERN.search(text):
                yield lineno, text


def chunked(iterable, size):
    batch = []
    for item in iterable:
        batch.append(item)
        if len(batch) == size:
            yield batch
            batch = []
    if batch:
        yield batch


def label_batch(client, batch):
    """batch: list of (lineno, text). Returns (flagged [(lineno, text)], model)."""
    state = {"lines": {str(i): text for i, (_, text) in enumerate(batch)}}
    questions = {f"q{i}": Noul(instructions=question_text(i)) for i in range(len(batch))}
    r = client.system_one(state=state, questions=questions, model=MODEL)
    flagged = [
        (lineno, text)
        for i, (lineno, text) in enumerate(batch)
        if r.nouls[f"q{i}"].noul > NOUL_THRESHOLD
    ]
    return flagged, r.model


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("log_file", help="path to the application log file")
    parser.add_argument("-o", "--output", default="flagged.txt", help="output path (default: flagged.txt)")
    args = parser.parse_args()

    candidates = list(read_candidates(args.log_file))
    if not candidates:
        open(args.output, "w").close()
        print("no candidate lines found; wrote empty output")
        return

    flagged_by_lineno = {}
    models_seen = set()

    with TypeSafeClient() as client:
        batches = list(chunked(candidates, BATCH_SIZE))
        with ThreadPoolExecutor(max_workers=MAX_WORKERS) as pool:
            futures = {pool.submit(label_batch, client, batch): batch for batch in batches}
            for future in as_completed(futures):
                batch = futures[future]
                try:
                    flagged, model = future.result()
                except TypeSafeError as e:
                    first_line = batch[0][0] + 1
                    print(f"warning: batch starting at line {first_line} failed: {e}", file=sys.stderr)
                    continue
                models_seen.add(model)
                for lineno, text in flagged:
                    flagged_by_lineno[lineno] = text

    with open(args.output, "w", encoding="utf-8") as f:
        for lineno in sorted(flagged_by_lineno):
            f.write(flagged_by_lineno[lineno] + "\n")

    print(
        f"{len(candidates)} candidate lines judged, {len(flagged_by_lineno)} flagged "
        f"-> {args.output} (model: {', '.join(sorted(models_seen)) or 'none'})"
    )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Flag log lines that need an on-call engineer, using typesafe.ai's Jev model.

Usage: python3 label_logs.py [log_path] [out_path]
Requires: pip install typesafe-sdk, and TYPESAFE_API_KEY set in the environment.
"""

import sys
from concurrent.futures import ThreadPoolExecutor, as_completed

from typesafe_sdk import Noul, NoulCriteria, TypeSafeClient

# Tunable constants: model, batch shape, and the paging threshold.
MODEL = "jev-1.13.0"
BATCH_SIZE = 50  # lines per request; keeps state well under the context limit
MAX_WORKERS = 8  # shared-key rate limit starts 429ing above this
THRESHOLD = 0.5  # noul > THRESHOLD -> flagged; flagged.txt is for human review, not auto-paging

NEEDS_ONCALL = NoulCriteria(
    true=(
        "An active outage, crash, service failure, data loss, security incident, "
        "or resource exhaustion that a human needs to act on right now."
    ),
    false=(
        "Normal operation, a successful completion, routine informational status, "
        "or a warning/error that resolves on its own without human action."
    ),
)


def chunk(seq, size):
    for i in range(0, len(seq), size):
        yield seq[i : i + size]


def build_questions(batch):
    return {
        f"line_{i}": Noul(
            instructions=(
                f"Does `lines[{i}]` report a problem serious enough that an "
                "on-call engineer needs to be paged right now?"
            ),
            criteria=NEEDS_ONCALL,
        )
        for i in range(len(batch))
    }


def label_batch(client, batch):
    response = client.system_one(
        state={"lines": batch},
        questions=build_questions(batch),
        model=MODEL,
    )
    return [response.nouls[f"line_{i}"].noul for i in range(len(batch))]


def main(log_path="log.txt", out_path="flagged.txt"):
    with open(log_path, encoding="utf-8", errors="replace") as f:
        lines = [line.rstrip("\n") for line in f if line.strip()]

    batches = list(chunk(lines, BATCH_SIZE))
    results = [None] * len(batches)

    with TypeSafeClient() as client:
        with ThreadPoolExecutor(max_workers=MAX_WORKERS) as pool:
            futures = {
                pool.submit(label_batch, client, batch): idx
                for idx, batch in enumerate(batches)
            }
            for future in as_completed(futures):
                results[futures[future]] = future.result()

    flagged = [
        line
        for batch, scores in zip(batches, results)
        for line, score in zip(batch, scores)
        if score > THRESHOLD
    ]

    with open(out_path, "w", encoding="utf-8") as f:
        for line in flagged:
            f.write(line + "\n")

    print(f"Flagged {len(flagged)} of {len(lines)} lines -> {out_path}")


if __name__ == "__main__":
    log_path = sys.argv[1] if len(sys.argv) > 1 else "log.txt"
    out_path = sys.argv[2] if len(sys.argv) > 2 else "flagged.txt"
    main(log_path, out_path)

from typesafe_sdk import Noul, NoulCriteria, TypeSafeClient

MODEL = "jev-1.13.0"
NOUL_THRESHOLD = 0.5

QUESTIONS = {
    "consistent": Noul(
        instructions=(
            "Does everything `agent_reply` states about the customer's situation match "
            "what the customer actually said in `customer_message`, with no contradictions, "
            "invented facts, or misremembered details?"
        ),
        criteria=NoulCriteria(
            true="The reply's claims about the customer's situation match `customer_message`",
            false="The reply contradicts, invents, or misstates something the customer said",
        ),
    ),
    "polite": Noul(
        instructions="Is the tone of `agent_reply` polite and respectful toward the customer?",
        criteria=NoulCriteria(
            true="Courteous, respectful tone",
            false="Curt, dismissive, sarcastic, or rude tone",
        ),
    ),
    "resolves_issue": Noul(
        instructions=(
            "Does `agent_reply` resolve the issue the customer raised in `customer_message`, "
            "by providing a working solution, completing the requested action, or giving "
            "clear, complete next steps that fully address the request?"
        ),
        criteria=NoulCriteria(
            true="The issue is solved, or the customer knows exactly what will happen next",
            false="The issue is left open, deflected, or only partially addressed",
        ),
    ),
    "promises_refund": Noul(
        instructions="Does `agent_reply` promise, offer, or commit to giving the customer a refund?",
        criteria=NoulCriteria(
            true="The reply commits to, offers, or guarantees a refund",
            false="No refund is promised (declining, redirecting to billing, or not mentioning refunds)",
        ),
    ),
}

PROBLEM_MESSAGES = {
    "consistent": "Reply is inconsistent with what the customer said",
    "polite": "Reply is not polite",
    "resolves_issue": "Reply does not resolve the customer's issue",
    "promises_refund": "Reply promises a refund, which only billing may do",
}

_client = TypeSafeClient()


def grade(customer_message: str, agent_reply: str) -> dict:
    response = _client.system_one(
        state={"customer_message": customer_message, "agent_reply": agent_reply},
        questions=QUESTIONS,
        model=MODEL,
    )

    nouls = {key: response.nouls[key].noul for key in QUESTIONS}

    problems = [
        PROBLEM_MESSAGES[key]
        for key in ("consistent", "polite", "resolves_issue")
        if nouls[key] < NOUL_THRESHOLD
    ]
    if nouls["promises_refund"] >= NOUL_THRESHOLD:
        problems.append(PROBLEM_MESSAGES["promises_refund"])

    quality = (
        nouls["consistent"]
        + nouls["polite"]
        + nouls["resolves_issue"]
        + (1 - nouls["promises_refund"])
    ) / 4
    score = round(1 + 9 * quality, 1)

    return {
        "score": score,
        "problems": problems,
        "answers": nouls,
        "model": response.model,
    }

